import { z } from "zod";
import type { Product } from "@/features/products/product.types";

export const COMMENT_MIN = 10;
export const COMMENT_MAX = 2000;

// Product ids are nanoids generated by the import (specs/product.md).
export const PRODUCT_ID_PATTERN = /^[A-Za-z0-9_-]{21}$/;

export const productIdSchema = z
  .string({ error: "Choose a product to review" })
  .regex(PRODUCT_ID_PATTERN, "Choose a product to review");

// Shared by the form (client) and the API (server). Unknown keys such as a
// client-sent `accountId` or `productName` are stripped: the author comes from
// the session and the product name from the catalog.
export const createFeedbackSchema = z.object({
  productId: productIdSchema,
  rating: z
    .number({ error: "Choose a rating" })
    .int("Rating must be a whole number of stars")
    .min(1, "Choose a rating")
    .max(5, "Rating must be at most 5 stars"),
  comment: z
    .string({ error: "Comment is required" })
    .trim()
    .min(COMMENT_MIN, `Comment must have at least ${COMMENT_MIN} characters`)
    .max(COMMENT_MAX, `Comment must have at most ${COMMENT_MAX} characters`),
});

export const listFeedbackSchema = z
  .object({
    limit: z.number().int().min(1).max(50).default(10),
  })
  .default({ limit: 10 });

export const hasReviewedSchema = z.object({ productId: productIdSchema });

export type CreateFeedbackInput = z.input<typeof createFeedbackSchema>;
export type CreateFeedbackData = z.output<typeof createFeedbackSchema>;

/** The product fields a review shows (thumbnail, title linking to Amazon). */
export type FeedbackProduct = Pick<
  Product,
  "id" | "title" | "imageUrl" | "url"
>;

/** What the feedback page needs to show the product being reviewed. */
export type ReviewedProduct = FeedbackProduct & Pick<Product, "priceCents">;

export type Feedback = {
  id: string;
  /** null for reviews from the first version (typed product name) */
  product: FeedbackProduct | null;
  /** Product title when the review was posted, or the typed name for old rows */
  productName: string;
  rating: number;
  comment: string;
  createdAt: Date;
};
